import{_ as e,r as o,o as c,c as i,a as n,b as s,d as t,e as p}from"./app-05339d0e.js";const l={},u=n("blockquote",null,[n("p",null,"Retrievel-Augmented Genration 检索 增强 生成"),n("p",null,"先从资料库检索相关内容，再基于内容生成答案"),n("p",null,"常用于智能客服或知识库")],-1),k={href:"https://github.com/MarkTechStation/VideoCode",target:"_blank",rel:"noopener noreferrer"},r=p('<h2 id="背景" tabindex="-1"><a class="header-anchor" href="#背景" aria-hidden="true">#</a> 背景</h2><p>如果将完整资料交给模型</p><ul><li>由于模型拥有有限的上下文，如果提供资料超过上下文大小，会出现读了后面，忘了前面。</li><li>且由于阅读量较大，每次回答都需阅读大量资料，推理成本过高</li><li>推理速度也会很慢</li></ul><p>将资料分片，每次从分片中获取与问题相关的片段，将这些片段与问题发送给大模型，实现更高效的问题解答</p><h2 id="基本流程" tabindex="-1"><a class="header-anchor" href="#基本流程" aria-hidden="true">#</a> 基本流程</h2><p>RAG 的基本流程分为两个阶段。对知识库文档先进行解析存储，即预处理阶段。后续在线问答阶段，则是根据用户的问题，在已存储的文档中查询语义相近的文档结果，根据内容做出回答</p><h3 id="预处理" tabindex="-1"><a class="header-anchor" href="#预处理" aria-hidden="true">#</a> 预处理</h3>',7),d=n("li",null,"分片: 拥有多种方式，如 按指定字数切分、按段落、按章节、按页码",-1),v={href:"https://huggingface.co/spaces/mteb/",target:"_blank",rel:"noopener noreferrer"},m=n("li",null,"将片段文本与向量存储进向量数据库中。向量数据库可用于存储与查询向量。后续得到向量后，查询相近的向量与对应的原始文本，从而实现后续发送给大模型。通常有两列，一列是原始文本，一列是解析得到的向量",-1),b=p(`<h3 id="回答" tabindex="-1"><a class="header-anchor" href="#回答" aria-hidden="true">#</a> 回答</h3><ul><li>召回: 搜索与用户问题相关的片段 <ul><li>将用户问题发送给 Embedding 模型，得到对应的向量</li><li>通过向量查询向量数据库，得到固定个数的最相似结果（计算向量相似度，成本低，准确率低，做初筛） <ul><li>余弦相似度: 计算相关夹角的 cos 值，即计算夹角大小，不关注向量长度的不同（仅关注方向，忽略强度）。该算法避免数量级带来的差异，</li><li>欧式距离: 计算向量的距离</li><li>点积: 计算向量 A 在向量 B 投影长度与向量 B 长度的乘积，越大相似度越高</li></ul></li></ul></li><li>重排: 重新排序。从召回得到的结果中，进行再次筛选，挑选出指定个数最相似的结果（使用 cross-encoder 模型计算与问题的相似度，成本高，准确率高，做复筛）</li><li>生成: 将重排结果与问题发送给大模型，大模型根据提供内容生成结果返回</li></ul><h2 id="代码实现" tabindex="-1"><a class="header-anchor" href="#代码实现" aria-hidden="true">#</a> 代码实现</h2><h3 id="安装依赖" tabindex="-1"><a class="header-anchor" href="#安装依赖" aria-hidden="true">#</a> 安装依赖</h3><p>使用 python 的 uv 进行包管理，安装相应的依赖</p><div class="macos language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>uv <span class="token function">add</span> sentence_transformers chromadb google-genai python-dotenv
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>以下是各个包的简介</p><ul><li>sentence_transformers: embedding 模型 与 cross-encoder 模型</li><li>chromadb: 向量数据库</li><li>google-genai: 调用 google gemini 的依赖，此处使用 gemini 作为生成阶段的大模型，因此需要安装此包</li><li>python-dotenv: 环境变量管理</li></ul><h3 id="分片" tabindex="-1"><a class="header-anchor" href="#分片" aria-hidden="true">#</a> 分片</h3><p>分片有多种分割方式，如按行、按字数、按章节等。这里介绍两种分片方式的实现</p><ul><li><p>按行切分</p><div class="language-python line-numbers-mode" data-ext="py"><pre class="language-python"><code><span class="token keyword">def</span> <span class="token function">split_into_chunks</span><span class="token punctuation">(</span>doc_file<span class="token punctuation">:</span> <span class="token builtin">str</span><span class="token punctuation">)</span> <span class="token operator">-</span><span class="token operator">&gt;</span> <span class="token builtin">list</span><span class="token punctuation">[</span><span class="token builtin">str</span><span class="token punctuation">]</span><span class="token punctuation">:</span>
    <span class="token keyword">with</span> <span class="token builtin">open</span><span class="token punctuation">(</span>doc_file<span class="token punctuation">,</span> <span class="token string">&#39;r&#39;</span><span class="token punctuation">)</span> <span class="token keyword">as</span> <span class="token builtin">file</span><span class="token punctuation">:</span>
        content <span class="token operator">=</span> <span class="token builtin">file</span><span class="token punctuation">.</span>read<span class="token punctuation">(</span><span class="token punctuation">)</span>
    <span class="token comment"># 按行进行切分</span>
    <span class="token keyword">return</span> <span class="token punctuation">[</span>chunk <span class="token keyword">for</span> chunk <span class="token keyword">in</span> content<span class="token punctuation">.</span>split<span class="token punctuation">(</span><span class="token string">&#39;\\n\\n&#39;</span><span class="token punctuation">)</span><span class="token punctuation">]</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></li><li><p>按字数切分。保证每个块有前后块的相邻字符，减少切分产生丢失语义的可能（经专业机构测试，10%-20%效果最优）</p><div class="language-python line-numbers-mode" data-ext="py"><pre class="language-python"><code><span class="token comment"># 传入原文，切分窗口大小（400），保留相邻块的字符数（100）</span>
<span class="token keyword">def</span> <span class="token function">split_text</span><span class="token punctuation">(</span>text<span class="token punctuation">:</span> <span class="token builtin">str</span><span class="token punctuation">,</span> chunk_size<span class="token punctuation">:</span> <span class="token builtin">int</span> <span class="token operator">=</span> CHUNK_SIZE<span class="token punctuation">,</span> overlap<span class="token punctuation">:</span> <span class="token builtin">int</span> <span class="token operator">=</span> CHUNK_OVERLAP<span class="token punctuation">)</span><span class="token punctuation">:</span>
    text <span class="token operator">=</span> text<span class="token punctuation">.</span>strip<span class="token punctuation">(</span><span class="token punctuation">)</span>
    <span class="token keyword">if</span> <span class="token keyword">not</span> text<span class="token punctuation">:</span>
        <span class="token keyword">return</span> <span class="token punctuation">[</span><span class="token punctuation">]</span>
    chunks <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token punctuation">]</span>
    start <span class="token operator">=</span> <span class="token number">0</span>
    <span class="token keyword">while</span> start <span class="token operator">&lt;</span> <span class="token builtin">len</span><span class="token punctuation">(</span>text<span class="token punctuation">)</span><span class="token punctuation">:</span>
        end <span class="token operator">=</span> start <span class="token operator">+</span> chunk_size
        chunks<span class="token punctuation">.</span>append<span class="token punctuation">(</span>text<span class="token punctuation">[</span>start<span class="token punctuation">:</span>end<span class="token punctuation">]</span><span class="token punctuation">)</span>
        start <span class="token operator">=</span> end <span class="token operator">-</span> overlap  <span class="token comment"># 跳转开始位置，重复一定量的字符</span>
    <span class="token keyword">return</span> chunk
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></li></ul><h3 id="索引" tabindex="-1"><a class="header-anchor" href="#索引" aria-hidden="true">#</a> 索引</h3><p>计算每个文本段的向量，将其进行存储</p><ul><li><p>文本转换成向量</p><ul><li><p>使用 sentence_transformers 解析向量。预训练好的通用模型，向量维度和语义空间是固定不变的，计算单条文本完全独立</p><div class="language-python line-numbers-mode" data-ext="py"><pre class="language-python"><code><span class="token keyword">from</span> sentence_transformers <span class="token keyword">import</span> SentenceTransformer

<span class="token comment"># 加载一个 embedding 模型 - 会从网上拉取大模型，要保证网络通畅</span>
embedding_model <span class="token operator">=</span> SentenceTransformer<span class="token punctuation">(</span><span class="token string">&#39;shibing624/text2vec-base-chinese&#39;</span><span class="token punctuation">)</span>

<span class="token comment"># 将文本转换成向量</span>
<span class="token keyword">def</span> <span class="token function">embed_chunk</span><span class="token punctuation">(</span>chunk<span class="token punctuation">:</span> <span class="token builtin">str</span><span class="token punctuation">)</span> <span class="token operator">-</span><span class="token operator">&gt;</span> <span class="token builtin">list</span><span class="token punctuation">[</span><span class="token builtin">float</span><span class="token punctuation">]</span><span class="token punctuation">:</span>
    embedding <span class="token operator">=</span> embedding_model<span class="token punctuation">.</span>encode<span class="token punctuation">(</span>chunk<span class="token punctuation">)</span>
    <span class="token keyword">return</span> embedding<span class="token punctuation">.</span>tolist<span class="token punctuation">(</span><span class="token punctuation">)</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></li><li><p>使用 scikit-learn 解析向量。<code>TfidfVectorizer</code>（传统统计学/稀疏向量）：基于当前数据集的统计规律（词频 + 逆文档频率），每个维度的含义和权重取决于整个语料库。</p><div class="language-python line-numbers-mode" data-ext="py"><pre class="language-python"><code><span class="token keyword">import</span> pickle
<span class="token keyword">from</span> sklearn<span class="token punctuation">.</span>feature_extraction<span class="token punctuation">.</span>text <span class="token keyword">import</span> TfidfVectorizer

VECTORIZER_PATH <span class="token operator">=</span> os<span class="token punctuation">.</span>path<span class="token punctuation">.</span>join<span class="token punctuation">(</span>DATA_DIR<span class="token punctuation">,</span> <span class="token string">&#39;vectorizer.pkl&#39;</span><span class="token punctuation">)</span>  <span class="token comment"># 存储向量解析</span>
<span class="token comment"># 向量解析器</span>
_vectorizer <span class="token operator">=</span> <span class="token boolean">None</span>

<span class="token keyword">def</span> <span class="token function">get_vectorizer</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">-</span><span class="token operator">&gt;</span> TfidfVectorizer<span class="token punctuation">:</span>
    <span class="token keyword">global</span> _vectorizer
    <span class="token keyword">if</span> <span class="token keyword">not</span> _vectorizer<span class="token punctuation">:</span>
        <span class="token comment"># 磁盘中已经存在</span>
        <span class="token keyword">if</span> os<span class="token punctuation">.</span>path<span class="token punctuation">.</span>exists<span class="token punctuation">(</span>VECTORIZER_PATH<span class="token punctuation">)</span><span class="token punctuation">:</span>
            <span class="token keyword">with</span> <span class="token builtin">open</span><span class="token punctuation">(</span>VECTORIZER_PATH<span class="token punctuation">,</span> <span class="token string">&#39;rb&#39;</span><span class="token punctuation">)</span> <span class="token keyword">as</span> f<span class="token punctuation">:</span>
                _vectorizer <span class="token operator">=</span> pickle<span class="token punctuation">.</span>load<span class="token punctuation">(</span>f<span class="token punctuation">)</span>
        <span class="token keyword">else</span><span class="token punctuation">:</span>
            _vectorizer <span class="token operator">=</span> TfidfVectorizer<span class="token punctuation">(</span>
                analyzer<span class="token operator">=</span><span class="token string">&#39;char_wb&#39;</span><span class="token punctuation">,</span> 
                ngram_range<span class="token operator">=</span><span class="token punctuation">(</span><span class="token number">2</span><span class="token punctuation">,</span> <span class="token number">4</span><span class="token punctuation">)</span><span class="token punctuation">,</span>
                max_features<span class="token operator">=</span><span class="token number">10000</span>
            <span class="token punctuation">)</span>
    <span class="token keyword">return</span> _vectorizer

<span class="token comment"># 传入多个块，得到多个块的向量</span>
<span class="token keyword">def</span> <span class="token function">add_new_chunks</span><span class="token punctuation">(</span>chunks<span class="token punctuation">:</span> <span class="token builtin">list</span><span class="token punctuation">[</span><span class="token builtin">str</span><span class="token punctuation">]</span><span class="token punctuation">)</span> <span class="token operator">-</span><span class="token operator">&gt;</span> <span class="token builtin">list</span><span class="token punctuation">[</span><span class="token builtin">list</span><span class="token punctuation">[</span>f<span class="token punctuation">]</span><span class="token punctuation">]</span><span class="token punctuation">:</span>
    vec <span class="token operator">=</span> get_vectorizer<span class="token punctuation">(</span><span class="token punctuation">)</span>
    <span class="token comment"># 获取文本的词汇表</span>
    vec<span class="token punctuation">.</span>fit<span class="token punctuation">(</span>chunks<span class="token punctuation">)</span>
    <span class="token comment"># 解析向量</span>
    embeddings <span class="token operator">=</span> vec<span class="token punctuation">.</span>transform<span class="token punctuation">(</span>chunks<span class="token punctuation">)</span>

    ret <span class="token operator">=</span> <span class="token punctuation">[</span>embedding<span class="token punctuation">.</span>toarray<span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">[</span><span class="token number">0</span><span class="token punctuation">]</span><span class="token punctuation">.</span>tolist<span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token keyword">for</span> embedding <span class="token keyword">in</span> embeddings<span class="token punctuation">]</span>

    <span class="token comment"># IDF 的计算必须依赖“全局语料”（文档全局统计）. TF-IDF=TF（词频）×IDF（逆文档频率）</span>
    <span class="token comment"># 刷新并加载向量器。每次添加新的文本，需要与旧文本一起训练。保证新文本与旧文本中，相近的语义，生成的向量也相近</span>
    <span class="token comment"># 用全量语料重建向量器，保证所有文档的向量在同一词汇空间</span>
    rebuild_vectorizer<span class="token punctuation">(</span><span class="token punctuation">)</span>
    _re_encode_all<span class="token punctuation">(</span><span class="token punctuation">)</span>

<span class="token comment"># 在全量 chunk 上重新训练向量器</span>
<span class="token keyword">def</span> <span class="token function">rebuild_vectorizer</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">:</span>
    <span class="token keyword">global</span> _vectorizer
    all_chunks <span class="token operator">=</span> storage<span class="token punctuation">.</span>get_all_chunks<span class="token punctuation">(</span><span class="token punctuation">)</span>
    <span class="token comment"># 从 chunks 的结构字典列表中获取 切片文本列表</span>
    texts <span class="token operator">=</span> <span class="token punctuation">[</span>c<span class="token punctuation">[</span><span class="token string">&#39;text&#39;</span><span class="token punctuation">]</span> <span class="token keyword">for</span> c <span class="token keyword">in</span> all_chunks<span class="token punctuation">]</span>
    _vectorizer <span class="token operator">=</span> TfidfVectorzier<span class="token punctuation">(</span>
        analyzer<span class="token operator">=</span><span class="token string">&#39;char_wb&#39;</span><span class="token punctuation">,</span> 
        ngram_range<span class="token operator">=</span><span class="token punctuation">(</span><span class="token number">2</span><span class="token punctuation">,</span> <span class="token number">4</span><span class="token punctuation">)</span><span class="token punctuation">,</span>
        max_features<span class="token operator">=</span><span class="token number">10000</span>
    <span class="token punctuation">)</span>
    _vectorizer<span class="token punctuation">.</span>fit<span class="token punctuation">(</span>texts<span class="token punctuation">)</span>
    <span class="token keyword">with</span> <span class="token builtin">open</span><span class="token punctuation">(</span>VECTORIZER_PATH<span class="token punctuation">,</span> <span class="token string">&#39;wb&#39;</span><span class="token punctuation">)</span> <span class="token keyword">as</span> f<span class="token punctuation">:</span>
        pickle<span class="token punctuation">.</span>dump<span class="token punctuation">(</span>_vectorizer<span class="token punctuation">,</span> f<span class="token punctuation">)</span>
    <span class="token keyword">return</span> _vectorizer

<span class="token comment"># 用新的全局向量器冲洗编码所有 chunk / 更新所有 chunk 的向量信息</span>
<span class="token keyword">def</span> <span class="token function">_re_encode_all</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">:</span>
    all_chunks <span class="token operator">=</span> storage<span class="token punctuation">.</span>get_all_chunks<span class="token punctuation">(</span><span class="token punctuation">)</span>
    <span class="token keyword">if</span> <span class="token keyword">not</span> all_chunks<span class="token punctuation">:</span>
        <span class="token keyword">return</span>
    vec <span class="token operator">=</span> get_vectorizer<span class="token punctuation">(</span><span class="token punctuation">)</span>
    <span class="token comment"># 从 chunks 的结构字典列表中获取 切片文本列表</span>
    texts <span class="token operator">=</span> <span class="token punctuation">[</span>c<span class="token punctuation">[</span><span class="token string">&#39;text&#39;</span><span class="token punctuation">]</span> <span class="token keyword">for</span> c <span class="token keyword">in</span> all_chunks<span class="token punctuation">]</span>
    matrices <span class="token operator">=</span> vec<span class="token punctuation">.</span>transform<span class="token punctuation">(</span>texts<span class="token punctuation">)</span>
    ds <span class="token operator">=</span> storage<span class="token punctuation">.</span>get_docstore<span class="token punctuation">(</span><span class="token punctuation">)</span>
    <span class="token keyword">for</span> i<span class="token punctuation">,</span> row <span class="token keyword">in</span> <span class="token builtin">enumerate</span><span class="token punctuation">(</span>matrices<span class="token punctuation">)</span><span class="token punctuation">:</span>
        <span class="token comment"># 更新向量信息</span>
        ds<span class="token punctuation">[</span><span class="token string">&#39;chunks&#39;</span><span class="token punctuation">]</span><span class="token punctuation">[</span>i<span class="token punctuation">]</span><span class="token punctuation">[</span><span class="token string">&#39;embedding&#39;</span><span class="token punctuation">]</span> <span class="token operator">=</span> row<span class="token punctuation">.</span>toarray<span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">[</span><span class="token number">0</span><span class="token punctuation">]</span><span class="token punctuation">.</span>tolist<span class="token punctuation">(</span><span class="token punctuation">)</span>
    storage<span class="token punctuation">.</span>save_docstore<span class="token punctuation">(</span>ds<span class="token punctuation">)</span>  <span class="token comment"># 存储</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></li></ul></li><li><p>向量存储</p><div class="language-python line-numbers-mode" data-ext="py"><pre class="language-python"><code><span class="token keyword">import</span> chromadb
<span class="token comment"># 数据库连接对象</span>
chromadb_client <span class="token operator">=</span> chromadb<span class="token punctuation">.</span>EphemeralClient<span class="token punctuation">(</span><span class="token punctuation">)</span>  <span class="token comment"># EphemeralClient 是内存型向量数据库，用于测试</span>
<span class="token comment"># chromadb_client = chromadb.PersistentClient(&#39;&lt;文件路径&gt;&#39;)  # 写入磁盘的数据库</span>
<span class="token comment"># 创建集合</span>
chromadb_collection <span class="token operator">=</span> chromadb_client<span class="token punctuation">.</span>get_or_create_collection<span class="token punctuation">(</span>name<span class="token operator">=</span><span class="token string">&#39;default&#39;</span><span class="token punctuation">)</span>
<span class="token comment"># 额外参数 \`metadata={&quot;hnsw:space&quot;: &quot;&quot;}\` 用于指明计算空间方式，后续查询相似向量时，使用此处指明的计算方式计算相似度</span>
<span class="token comment"># - &quot;l2&quot; (默认)：平方欧氏距离。图像向量、空间几何特征等对长度敏感的数据</span>
<span class="token comment"># - &quot;cosine&quot;：余弦距离。文本检索 / RAG 最推荐（排除了文本长度与模长影响）</span>
<span class="token comment"># - &quot;ip&quot;：内积 / 点积 (Inner Product)。已经提前做过归一化的向量，速度更快</span>

<span class="token comment"># 传入 原文数组 与 对应的多个向量 进行保存</span>
<span class="token keyword">def</span> <span class="token function">save_embeddings</span><span class="token punctuation">(</span>chunks<span class="token punctuation">:</span> <span class="token builtin">list</span><span class="token punctuation">[</span><span class="token builtin">str</span><span class="token punctuation">]</span><span class="token punctuation">,</span> embeddings<span class="token punctuation">:</span> <span class="token builtin">list</span><span class="token punctuation">[</span><span class="token builtin">list</span><span class="token punctuation">[</span><span class="token builtin">float</span><span class="token punctuation">]</span><span class="token punctuation">]</span><span class="token punctuation">)</span> <span class="token operator">-</span><span class="token operator">&gt;</span> <span class="token boolean">None</span><span class="token punctuation">:</span>
    <span class="token comment"># chromadb 要求每条数据需要有 ID，这里生成一个 ID 列表</span>
    ids <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token builtin">str</span><span class="token punctuation">(</span>i<span class="token punctuation">)</span> <span class="token keyword">for</span> i <span class="token keyword">in</span> <span class="token builtin">range</span><span class="token punctuation">(</span><span class="token builtin">len</span><span class="token punctuation">(</span>chunks<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">]</span>  
    <span class="token comment"># 存储入库</span>
    chromadb_collection<span class="token punctuation">.</span>add<span class="token punctuation">(</span>
        documents<span class="token operator">=</span>chunks<span class="token punctuation">,</span>
        embeddings<span class="token operator">=</span>embeddings<span class="token punctuation">,</span>
        ids<span class="token operator">=</span>ids
    <span class="token punctuation">)</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></li></ul><p><strong>Tip:</strong> 在现代检索（RAG、语义搜索）中，更推崇预训练的 Embedding 模型，正是因为它们在增量插入数据时只需要对新切片计算一次，旧切片的向量持久化后永久有效，工程维护成本极低。TF-IDF 虽然单次计算极快，但语料库越大，增量更新的代价（全量重算）越可怕</p><h3 id="召回" tabindex="-1"><a class="header-anchor" href="#召回" aria-hidden="true">#</a> 召回</h3><p>将问题转换成向量，并查询语义相近的向量结果</p><ul><li><p>使用 embedding 模型进行召回</p><div class="language-python line-numbers-mode" data-ext="py"><pre class="language-python"><code><span class="token comment"># 传入问题与召回数量，得到多个召回结果</span>
<span class="token keyword">def</span> <span class="token function">retrieve</span><span class="token punctuation">(</span>query<span class="token punctuation">:</span> <span class="token builtin">str</span><span class="token punctuation">,</span> top_k<span class="token punctuation">:</span> <span class="token builtin">int</span><span class="token punctuation">)</span> <span class="token operator">-</span><span class="token operator">&gt;</span> <span class="token builtin">list</span><span class="token punctuation">[</span><span class="token builtin">str</span><span class="token punctuation">]</span><span class="token punctuation">:</span>
    <span class="token comment"># 将问题解析成向量</span>
    query_embedding <span class="token operator">=</span> embed_chunk<span class="token punctuation">(</span>query<span class="token punctuation">)</span>
    <span class="token comment"># 根据向量在数据库中查询出结果</span>
    results <span class="token operator">=</span> chromadb_collection<span class="token punctuation">.</span>query<span class="token punctuation">(</span>
        query_embeddings<span class="token operator">=</span><span class="token punctuation">[</span>qyery_embedding<span class="token punctuation">]</span><span class="token punctuation">,</span>
        n_results<span class="token operator">=</span>top_k
    <span class="token punctuation">)</span>
    <span class="token keyword">return</span> results<span class="token punctuation">[</span><span class="token string">&#39;documents&#39;</span><span class="token punctuation">]</span><span class="token punctuation">[</span><span class="token number">0</span><span class="token punctuation">]</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></li><li><p>使用 scikit-learn 的 <code>TfidfVectorizer</code> 召回。将问题转换成 TF-IDF 向量，与所有 chunk 计算余弦相似度</p><div class="language-python line-numbers-mode" data-ext="py"><pre class="language-python"><code><span class="token keyword">from</span> sklearn<span class="token punctuation">.</span>metrics<span class="token punctuation">.</span>pairwise <span class="token keyword">import</span> cosine_similarity

<span class="token keyword">def</span> <span class="token function">retrieve</span><span class="token punctuation">(</span>query<span class="token punctuation">:</span> <span class="token builtin">str</span><span class="token punctuation">,</span> top_k<span class="token punctuation">:</span> <span class="token builtin">int</span> <span class="token operator">=</span> <span class="token number">4</span><span class="token punctuation">)</span> <span class="token operator">-</span><span class="token operator">&gt;</span> <span class="token builtin">list</span><span class="token punctuation">[</span><span class="token builtin">dict</span><span class="token punctuation">]</span>
    all_chunks <span class="token operator">=</span> storage<span class="token punctuation">.</span>get_all_chunks<span class="token punctuation">(</span><span class="token punctuation">)</span>
    <span class="token keyword">if</span> <span class="token keyword">not</span> all_chunks<span class="token punctuation">:</span>
        <span class="token keyword">return</span> <span class="token punctuation">[</span><span class="token punctuation">]</span>
    vec <span class="token operator">=</span> get_vectorizer<span class="token punctuation">(</span><span class="token punctuation">)</span>
    query_embedding <span class="token operator">=</span> vec<span class="token punctuation">.</span>tranform<span class="token punctuation">(</span><span class="token punctuation">[</span>query<span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">.</span>toarray<span class="token punctuation">(</span><span class="token punctuation">)</span>
    chunks_embeddings <span class="token operator">=</span> np<span class="token punctuation">.</span>array<span class="token punctuation">(</span><span class="token punctuation">[</span>c<span class="token punctuation">[</span><span class="token string">&#39;embedding&#39;</span><span class="token punctuation">]</span> <span class="token keyword">for</span> c <span class="token keyword">in</span> all_chunks<span class="token punctuation">]</span><span class="token punctuation">)</span>
    <span class="token comment"># 计算余弦相似度</span>
    sims <span class="token operator">=</span> consine_similarity<span class="token punctuation">(</span>query_embedding<span class="token punctuation">,</span> chunks_embeddings<span class="token punctuation">)</span><span class="token punctuation">[</span><span class="token number">0</span><span class="token punctuation">]</span>
    ranked <span class="token operator">=</span> <span class="token builtin">sorted</span><span class="token punctuation">(</span><span class="token builtin">zip</span><span class="token punctuation">(</span>all_chunks<span class="token punctuation">,</span> sims<span class="token punctuation">)</span><span class="token punctuation">,</span> key<span class="token operator">=</span><span class="token keyword">lambda</span> x<span class="token punctuation">:</span> x<span class="token punctuation">[</span><span class="token number">1</span><span class="token punctuation">]</span><span class="token punctuation">,</span> reverse<span class="token operator">=</span><span class="token boolean">True</span><span class="token punctuation">)</span>
    top <span class="token operator">=</span> ranked<span class="token punctuation">[</span><span class="token punctuation">:</span>top_k<span class="token punctuation">]</span>

    <span class="token keyword">return</span> <span class="token punctuation">[</span>chunk <span class="token keyword">for</span> chunk<span class="token punctuation">,</span> _ <span class="token keyword">in</span> top<span class="token punctuation">]</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></li></ul><h3 id="重排" tabindex="-1"><a class="header-anchor" href="#重排" aria-hidden="true">#</a> 重排</h3><p>在使用召回得到语义相近的文本后，使用成本更高的 cross-encoder 模型再次计算这些文本与问题的相似度，重新进行排序。以提高回答的准确率</p><div class="language-python line-numbers-mode" data-ext="py"><pre class="language-python"><code><span class="token keyword">from</span> sentence_transformers <span class="token keyword">import</span> CrossEncoder

<span class="token comment"># 传入 问题，召回结果，复筛个数，得到 重排结果列表</span>
<span class="token keyword">def</span> <span class="token function">rerank</span><span class="token punctuation">(</span>query<span class="token punctuation">:</span> <span class="token builtin">str</span><span class="token punctuation">,</span> retrieved_chunks<span class="token punctuation">:</span> <span class="token builtin">list</span><span class="token punctuation">[</span><span class="token builtin">str</span><span class="token punctuation">]</span><span class="token punctuation">,</span> top_k<span class="token punctuation">:</span> <span class="token builtin">int</span><span class="token punctuation">)</span> <span class="token operator">-</span><span class="token operator">&gt;</span> <span class="token builtin">list</span><span class="token punctuation">[</span><span class="token builtin">str</span><span class="token punctuation">]</span><span class="token punctuation">:</span>
    <span class="token comment"># 创建 cross_encoder 模型 - 也会从网上拉取大模型，要保证网络通畅</span>
    cross_encoder <span class="token operator">=</span> CrossEncoder<span class="token punctuation">(</span><span class="token string">&#39;cross-encoder/mmarco-mMiniLMv2-L12-H384-v1&#39;</span><span class="token punctuation">)</span>
    <span class="token comment"># 创建问题与原文一一对应的列表</span>
    pairs <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token punctuation">(</span>query<span class="token punctuation">,</span> chunk<span class="token punctuation">)</span> <span class="token keyword">for</span> chunk <span class="token keyword">in</span> retrieved_chunks<span class="token punctuation">]</span>
    <span class="token comment"># 计算每个召回的原文与问题的相似度</span>
    scores <span class="token operator">=</span> cross_encoder<span class="token punctuation">.</span>predict<span class="token punctuation">(</span>pairs<span class="token punctuation">)</span>
    <span class="token comment"># 创建原文与评分一一对应的列表 [(原文, 分数), (原文, 分数)]</span>
    chunk_with_score_list <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token punctuation">(</span>chunk<span class="token punctuation">,</span> score<span class="token punctuation">)</span> <span class="token keyword">for</span> chunk<span class="token punctuation">,</span> score <span class="token keyword">in</span> <span class="token builtin">zip</span><span class="token punctuation">(</span>retrieved_chunks<span class="token punctuation">,</span> scores<span class="token punctuation">)</span><span class="token punctuation">]</span>
    <span class="token comment"># 按照分数重新排序</span>
    chunk_with_score_list<span class="token punctuation">.</span>sort<span class="token punctuation">(</span>key<span class="token operator">=</span><span class="token keyword">lambda</span> pair<span class="token punctuation">:</span> pair<span class="token punctuation">[</span><span class="token number">1</span><span class="token punctuation">]</span>， reverse<span class="token operator">=</span><span class="token boolean">True</span><span class="token punctuation">)</span>
    <span class="token comment"># 返回截取后的结果</span>
    <span class="token keyword">return</span> <span class="token punctuation">[</span>chunk <span class="token keyword">for</span> chunk<span class="token punctuation">,</span> _ <span class="token keyword">in</span> chunk_with_score_list<span class="token punctuation">]</span><span class="token punctuation">[</span><span class="token punctuation">:</span>top_k<span class="token punctuation">]</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="生成" tabindex="-1"><a class="header-anchor" href="#生成" aria-hidden="true">#</a> 生成</h3>`,22),g={href:"https://aistudio.google.com/apikey",target:"_blank",rel:"noopener noreferrer"},y=p(`<ul><li>创建 <em>.env</em> 文件并写入 API KEY<div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>GEMINI_API_KEY=*****
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div></li><li>在配置好 API KEY 后编写调用大模型的代码。构造提示词传递给大模型，让其生成回复结果<div class="language-python line-numbers-mode" data-ext="py"><pre class="language-python"><code><span class="token keyword">from</span> dotenv <span class="token keyword">import</span> load_dotenv
<span class="token keyword">from</span> google <span class="token keyword">import</span> genai

load_dotenv<span class="token punctuation">(</span><span class="token punctuation">)</span>  <span class="token comment"># .env 中的内容设置为环境变量</span>

<span class="token comment"># 创建 gemini 客户端，会从环境变量中读取 GEMINI_API_KEY 的值</span>
google_client <span class="token operator">=</span> genai<span class="token punctuation">.</span>Client<span class="token punctuation">(</span><span class="token punctuation">)</span>

<span class="token keyword">def</span> <span class="token function">generate</span><span class="token punctuation">(</span>query<span class="token punctuation">:</span> <span class="token builtin">str</span><span class="token punctuation">,</span> chunks<span class="token punctuation">:</span> <span class="token builtin">list</span><span class="token punctuation">[</span><span class="token builtin">str</span><span class="token punctuation">]</span><span class="token punctuation">)</span> <span class="token operator">-</span><span class="token operator">&gt;</span> <span class="token builtin">str</span><span class="token punctuation">:</span>
    <span class="token comment"># 构建输入大模型的 prompt</span>
    prompt <span class="token operator">=</span> <span class="token string-interpolation"><span class="token string">f&quot;&quot;&quot;你是一位知识助手，请根据用户问题和下列片段生成准确的答案。

用户问题: </span><span class="token interpolation"><span class="token punctuation">{</span>query<span class="token punctuation">}</span></span><span class="token string">

相关片段: 
</span><span class="token interpolation"><span class="token punctuation">{</span><span class="token string">&quot;\\n\\n&quot;</span><span class="token punctuation">.</span>join<span class="token punctuation">(</span>chunks<span class="token punctuation">)</span><span class="token punctuation">}</span></span><span class="token string">

请基于上述内容作答，不要编造信息。&quot;&quot;&quot;</span></span>
    
    <span class="token comment"># 获取大模型根据输入的提示词得到的结果</span>
    response <span class="token operator">=</span> google_client<span class="token punctuation">.</span>models<span class="token punctuation">.</span>generate_content<span class="token punctuation">(</span>
        model<span class="token operator">=</span><span class="token string">&#39;gemini-2.5-flash&#39;</span><span class="token punctuation">,</span>
        contents<span class="token operator">=</span>prompt
    <span class="token punctuation">)</span>
    <span class="token keyword">return</span> response<span class="token punctuation">.</span>text
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></li></ul><p>如果需要 SSE 流式返回，并让大模型记住历史消息，可参考以下代码</p><div class="language-python line-numbers-mode" data-ext="py"><pre class="language-python"><code><span class="token comment"># 构造系统提示词 - 传入召回的文本内容</span>
<span class="token keyword">def</span> <span class="token function">_build_system_prompt</span><span class="token punctuation">(</span>context_texts<span class="token punctuation">:</span> <span class="token builtin">list</span><span class="token punctuation">[</span><span class="token builtin">str</span><span class="token punctuation">]</span><span class="token punctuation">)</span> <span class="token operator">-</span><span class="token operator">&gt;</span> <span class="token builtin">str</span><span class="token punctuation">:</span>
    <span class="token keyword">if</span> <span class="token keyword">not</span> context_texts<span class="token punctuation">:</span>
        <span class="token keyword">return</span> <span class="token string">&#39;你是一个知识库助手。当前知识库为空，请告知用户先上传文档&#39;</span>
    <span class="token comment"># 将所有召回的文本内容拼接到提示词中</span>
    ctx <span class="token operator">=</span> <span class="token string">&#39;\\n---\\n&#39;</span><span class="token punctuation">.</span>join<span class="token punctuation">(</span>context_texts<span class="token punctuation">)</span>
    <span class="token keyword">return</span> <span class="token punctuation">(</span>
        <span class="token string">&#39;你是一个知识库助手。请仅根据以下资料回答用户的问题，&#39;</span>
        <span class="token string">&#39;如果资料中没有答案，请如实说”知识库中暂无相关内容“\\n\\n&#39;</span>
        <span class="token string-interpolation"><span class="token string">f&#39;【参考资料】\\n</span><span class="token interpolation"><span class="token punctuation">{</span>ctx<span class="token punctuation">}</span></span><span class="token string">&#39;</span></span>
    <span class="token punctuation">)</span>

<span class="token comment"># RAG 问题处理的 SSE 流式会话函数</span>
<span class="token keyword">def</span> <span class="token function">stream_chat</span><span class="token punctuation">(</span>history_messages<span class="token punctuation">:</span> <span class="token builtin">list</span><span class="token punctuation">[</span><span class="token builtin">str</span><span class="token punctuation">]</span><span class="token punctuation">,</span> query<span class="token punctuation">:</span> <span class="token builtin">str</span><span class="token punctuation">,</span> top_k<span class="token punctuation">:</span> <span class="token builtin">int</span> <span class="token operator">=</span> RETRIEVAL_TOP_K<span class="token punctuation">)</span> <span class="token operator">-</span><span class="token operator">&gt;</span> Iterator<span class="token punctuation">[</span><span class="token builtin">str</span><span class="token punctuation">]</span><span class="token punctuation">:</span>
    <span class="token comment"># 获取召回的 chunk 列表</span>
    retrived <span class="token operator">=</span> rag<span class="token punctuation">,</span>retrieve<span class="token punctuation">(</span>query<span class="token punctuation">,</span> top_k<span class="token punctuation">)</span>
    <span class="token comment"># 获取召回的原文内容</span>
    context_texts <span class="token operator">=</span> <span class="token punctuation">[</span>c<span class="token punctuation">[</span><span class="token string">&#39;text&#39;</span><span class="token punctuation">]</span> <span class="token keyword">for</span> c <span class="token keyword">in</span> retrieved<span class="token punctuation">]</span>
    <span class="token comment"># 获取系统提示词</span>
    system <span class="token operator">=</span> _build_system_prompt<span class="token punctuation">(</span>context_texts<span class="token punctuation">)</span>
    
    <span class="token comment"># 组装历史消息</span>
    messages <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token punctuation">{</span><span class="token string">&#39;role&#39;</span><span class="token punctuation">:</span> <span class="token string">&#39;system&#39;</span><span class="token punctuation">,</span> <span class="token string">&#39;context&#39;</span><span class="token punctuation">:</span> system<span class="token punctuation">}</span><span class="token punctuation">]</span>
    <span class="token keyword">for</span> m <span class="token keyword">in</span> history_messages<span class="token punctuation">:</span>
        messages<span class="token punctuation">.</span>append<span class="token punctuation">(</span><span class="token punctuation">{</span><span class="token string">&#39;role&#39;</span><span class="token punctuation">:</span> m<span class="token punctuation">[</span><span class="token string">&#39;role&#39;</span><span class="token punctuation">]</span><span class="token punctuation">,</span> <span class="token string">&#39;content&#39;</span><span class="token punctuation">:</span> m<span class="token punctuation">[</span><span class="token string">&#39;content&#39;</span><span class="token punctuation">]</span><span class="token punctuation">}</span><span class="token punctuation">)</span>
    messages<span class="token punctuation">.</span>append<span class="token punctuation">(</span><span class="token punctuation">{</span><span class="token string">&#39;role&#39;</span><span class="token punctuation">:</span> <span class="token string">&#39;user&#39;</span><span class="token punctuation">,</span> <span class="token string">&#39;content&#39;</span><span class="token punctuation">:</span> query<span class="token punctuation">}</span><span class="token punctuation">)</span>

    <span class="token keyword">try</span><span class="token punctuation">:</span>
        <span class="token keyword">for</span> token <span class="token keyword">in</span> chat_stream<span class="token punctuation">(</span>messages<span class="token punctuation">)</span><span class="token punctuation">:</span>  <span class="token comment"># 此处调用发送大模型得到 stream 返回的 chat_stream 函数</span>
            <span class="token comment"># 将返回的字符转换成 json 字符串，便于后续在前方拼接 &quot;data:&quot;</span>
            payload <span class="token operator">=</span> json<span class="token punctuation">.</span>dumps<span class="token punctuation">(</span><span class="token punctuation">{</span><span class="token string">&#39;type&#39;</span><span class="token punctuation">:</span> <span class="token string">&#39;content&#39;</span><span class="token punctuation">,</span> <span class="token string">&#39;text&#39;</span><span class="token punctuation">:</span> token<span class="token punctuation">}</span><span class="token punctuation">,</span> ensure_ascii<span class="token operator">=</span><span class="token boolean">False</span><span class="token punctuation">)</span>
            <span class="token keyword">yield</span> <span class="token string-interpolation"><span class="token string">f&#39;data: </span><span class="token interpolation"><span class="token punctuation">{</span>payload<span class="token punctuation">}</span></span><span class="token string">\\n\\n&#39;</span></span>
        <span class="token keyword">yield</span> <span class="token string-interpolation"><span class="token string">f&#39;data: [DONE]\\n\\n&#39;</span></span>
    <span class="token keyword">except</span> Exception <span class="token keyword">as</span> e<span class="token punctuation">:</span>
        payload <span class="token operator">=</span> json<span class="token punctuation">.</span>dumps<span class="token punctuation">(</span><span class="token punctuation">{</span><span class="token string">&#39;type&#39;</span><span class="token punctuation">:</span> <span class="token string">&#39;error&#39;</span><span class="token punctuation">,</span> <span class="token string">&#39;message&#39;</span><span class="token punctuation">:</span> <span class="token builtin">str</span><span class="token punctuation">(</span>e<span class="token punctuation">)</span><span class="token punctuation">,</span> ensure_ascii<span class="token operator">=</span><span class="token boolean">False</span><span class="token punctuation">}</span><span class="token punctuation">)</span>
        <span class="token keyword">yield</span> <span class="token string-interpolation"><span class="token string">f&#39;data: </span><span class="token interpolation"><span class="token punctuation">{</span>payload<span class="token punctuation">}</span></span><span class="token string">\\n\\n&#39;</span></span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="大模型对话后端接口" tabindex="-1"><a class="header-anchor" href="#大模型对话后端接口" aria-hidden="true">#</a> 大模型对话后端接口</h2><p>由于最终效果是用户通过对话框实现文本内容的检索，需要实现大模型对话功能</p><p>在接入大模型时，每个大模型接入的 SDK 不同，最终可使用 langchain 封装，实现修改极少量代码可接入不同的大模型</p><p>此处不对 langchain 做赘述。按照 deepseek 官方文档，介绍如何介入 deepseek。由于文档中说明可使用 openai 的 sdk 接入，安装 openai 的依赖</p><div class="macos language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>pip <span class="token function">install</span> openai
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>以下是 <em>Flask</em> 后端接口的实现流程</p><ul><li><p>对话模块：deepseek 兼容 openai 的规范，可使用 OpenAI 的 sdk 进行接入</p><div class="language-python line-numbers-mode" data-ext="py"><pre class="language-python"><code><span class="token keyword">from</span> openai <span class="token keyword">import</span> OpenAI

_client <span class="token operator">=</span> <span class="token boolean">None</span>

<span class="token keyword">def</span> <span class="token function">get_client</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">-</span><span class="token operator">&gt;</span> OpenAI<span class="token punctuation">:</span>
    <span class="token keyword">global</span> _client
    <span class="token keyword">if</span> <span class="token keyword">not</span> _client<span class="token punctuation">:</span>
        _client <span class="token operator">=</span> OpenAI<span class="token punctuation">(</span>
            api_key<span class="token operator">=</span>API_KEY<span class="token punctuation">,</span>
            base_url<span class="token operator">=</span>BASE_URL
        <span class="token punctuation">)</span>
    <span class="token keyword">return</span> _client

<span class="token comment"># 传入记录会话消息历史的数组，每条记录包含发送人和内容的字典</span>
<span class="token keyword">def</span> <span class="token function">chat_stream</span><span class="token punctuation">(</span>messages<span class="token punctuation">:</span> <span class="token builtin">list</span><span class="token punctuation">[</span><span class="token builtin">dict</span><span class="token punctuation">]</span><span class="token punctuation">)</span> <span class="token operator">-</span><span class="token operator">&gt;</span> Iterator<span class="token punctuation">[</span><span class="token builtin">str</span><span class="token punctuation">]</span>
    stream <span class="token operator">=</span> get_client<span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span>chat<span class="token punctuation">.</span>completions<span class="token punctuation">.</span>create<span class="token punctuation">(</span>
        model<span class="token operator">=</span>DEEPSEEK_MODEL<span class="token punctuation">,</span>  <span class="token comment"># deepseek-v4-flash</span>
        messages<span class="token operator">=</span>messages<span class="token punctuation">,</span>
        stream<span class="token operator">=</span><span class="token boolean">True</span><span class="token punctuation">,</span>  <span class="token comment"># 流式输出</span>
        temperature<span class="token operator">=</span><span class="token number">0.7</span><span class="token punctuation">,</span>
        max_tokens<span class="token operator">=</span><span class="token number">2048</span>
    <span class="token punctuation">)</span>
    <span class="token keyword">for</span> chunk <span class="token keyword">in</span> stream<span class="token punctuation">:</span>
        delta <span class="token operator">=</span> chunk<span class="token punctuation">.</span>choices<span class="token punctuation">[</span><span class="token number">0</span><span class="token punctuation">]</span><span class="token punctuation">.</span>delta  <span class="token comment"># 根据 ds 官网的接收格式，获取大模型返回内容</span>
        <span class="token keyword">if</span> delta<span class="token punctuation">.</span>content<span class="token punctuation">:</span>  <span class="token comment"># 判断返回是否包含内容</span>
            <span class="token keyword">yield</span> delta<span class="token punctuation">.</span>content
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></li><li><p>利用对话模块编写一个终端会话功能函数</p><div class="language-python line-numbers-mode" data-ext="py"><pre class="language-python"><code><span class="token keyword">def</span> <span class="token function">chat_in_cli</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">:</span>
    <span class="token keyword">print</span><span class="token punctuation">(</span><span class="token string">&#39;deepseek 控制台对话&#39;</span><span class="token punctuation">)</span>
    <span class="token comment"># 记录会话消息的数组</span>
    messages <span class="token operator">=</span> <span class="token punctuation">[</span>
        <span class="token punctuation">{</span><span class="token string">&#39;role&#39;</span><span class="token punctuation">:</span> <span class="token string">&#39;system&#39;</span><span class="token punctuation">,</span> <span class="token string">&#39;content&#39;</span><span class="token punctuation">:</span> <span class="token string">&#39;你是一个助手，请用中文回答问题&#39;</span><span class="token punctuation">}</span>  <span class="token comment"># 默认消息中第一条为系统提示词</span>
    <span class="token punctuation">]</span>
    <span class="token keyword">while</span> <span class="token boolean">True</span><span class="token punctuation">:</span>
        user_input <span class="token operator">=</span> <span class="token builtin">input</span><span class="token punctuation">(</span><span class="token string">&#39;\\n你：&#39;</span><span class="token punctuation">)</span><span class="token punctuation">.</span>strip<span class="token punctuation">(</span><span class="token punctuation">)</span>  <span class="token comment"># 获取用户输入</span>
        <span class="token keyword">if</span> <span class="token keyword">not</span> user_input<span class="token punctuation">:</span>
            <span class="token keyword">continue</span>
        <span class="token keyword">if</span> user_input<span class="token punctuation">.</span>lower<span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token keyword">in</span> <span class="token punctuation">(</span><span class="token string">&#39;exit&#39;</span><span class="token punctuation">,</span> <span class="token string">&#39;quit&#39;</span><span class="token punctuation">)</span><span class="token punctuation">:</span>
            <span class="token keyword">print</span><span class="token punctuation">(</span><span class="token string">&#39;再见&#39;</span><span class="token punctuation">)</span>
            <span class="token keyword">break</span>
        <span class="token comment"># 在记录消息记录的数组内追加用户输入</span>
        messages<span class="token punctuation">.</span>append<span class="token punctuation">(</span><span class="token punctuation">{</span><span class="token string">&#39;role&#39;</span><span class="token punctuation">:</span> <span class="token string">&#39;user&#39;</span><span class="token punctuation">,</span> <span class="token string">&#39;content&#39;</span><span class="token punctuation">:</span> user_input<span class="token punctuation">}</span><span class="token punctuation">)</span>
        <span class="token keyword">print</span><span class="token punctuation">(</span><span class="token string">&#39;助手: &#39;</span><span class="token punctuation">,</span>end<span class="token operator">=</span><span class="token string">&#39;&#39;</span><span class="token punctuation">,</span> flush<span class="token operator">=</span><span class="token boolean">True</span><span class="token punctuation">)</span>
        <span class="token comment"># 存储大模型返回的答案流</span>
        full_anwser <span class="token operator">=</span> <span class="token string">&#39;&#39;</span>
        <span class="token keyword">for</span> token <span class="token keyword">in</span> chat_stream<span class="token punctuation">(</span>messages<span class="token punctuation">)</span><span class="token punctuation">:</span>  <span class="token comment"># 每次与大模型对话都传入完整的消息记录数组</span>
            <span class="token keyword">print</span><span class="token punctuation">(</span>token<span class="token punctuation">,</span> end<span class="token operator">=</span><span class="token string">&#39;&#39;</span><span class="token punctuation">,</span> flush<span class="token operator">=</span><span class="token boolean">True</span><span class="token punctuation">)</span>  <span class="token comment"># print 默认每次输出会换行，将换行取消并立即刷新</span>
            full_anwser <span class="token operator">+=</span> token
        <span class="token comment"># 换行处理</span>
        <span class="token keyword">print</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
        <span class="token comment"># 将大模型返回的答案放进消息记录数组内</span>
        messages<span class="token punctuation">.</span>append<span class="token punctuation">(</span><span class="token punctuation">{</span><span class="token string">&#39;role&#39;</span><span class="token punctuation">:</span> <span class="token string">&#39;assistant&#39;</span><span class="token punctuation">,</span> <span class="token string">&#39;content&#39;</span><span class="token punctuation">:</span> full_answer<span class="token punctuation">}</span><span class="token punctuation">)</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></li><li><p>SSE 流式会话函数。大模型返回时，会一个字一个字返回。最终返回 <code>[DONE]</code> 表示大模型的此次内容输出已经结束</p><div class="language-python line-numbers-mode" data-ext="py"><pre class="language-python"><code><span class="token comment"># 固定格式 \`data: &lt;内容&gt;\`</span>
<span class="token comment"># data: {&quot;type&quot;: &quot;content&quot;,&quot;text&quot;: &quot;你&quot;}</span>
<span class="token comment"># data: {&quot;type&quot;: &quot;content&quot;,&quot;text&quot;: &quot;好&quot;}</span>
<span class="token comment"># data: [DONE]</span>

<span class="token comment"># 传入完整的消息记录数组与本次的问题</span>
<span class="token keyword">def</span> <span class="token function">stream_chat</span><span class="token punctuation">(</span>history_messages<span class="token punctuation">:</span> <span class="token builtin">list</span><span class="token punctuation">[</span><span class="token builtin">dict</span><span class="token punctuation">]</span><span class="token punctuation">,</span> query<span class="token punctuation">:</span> <span class="token builtin">str</span><span class="token punctuation">)</span> <span class="token operator">-</span><span class="token operator">&gt;</span> Iterator<span class="token punctuation">[</span><span class="token builtin">str</span><span class="token punctuation">]</span><span class="token punctuation">:</span>
    <span class="token comment"># 参考终端会话功能函数，用一个数组记录完整的消息历史</span>
    messages <span class="token operator">=</span> <span class="token punctuation">[</span>
        <span class="token punctuation">{</span><span class="token string">&#39;role&#39;</span><span class="token punctuation">:</span> <span class="token string">&#39;system&#39;</span><span class="token punctuation">,</span> <span class="token string">&#39;content&#39;</span><span class="token punctuation">:</span> <span class="token string">&#39;你是一个助手，请用中文回答问题&#39;</span><span class="token punctuation">}</span>  <span class="token comment"># 默认消息中第一条为系统提示词]</span>
    <span class="token punctuation">]</span>
    <span class="token keyword">for</span> m <span class="token keyword">in</span> history_messages<span class="token punctuation">:</span>
        messages<span class="token punctuation">.</span>append<span class="token punctuation">(</span><span class="token punctuation">{</span>
            <span class="token string">&#39;role&#39;</span><span class="token punctuation">:</span> m<span class="token punctuation">[</span><span class="token string">&#39;role&#39;</span><span class="token punctuation">]</span><span class="token punctuation">,</span> <span class="token string">&#39;content&#39;</span><span class="token punctuation">:</span> m<span class="token punctuation">[</span><span class="token string">&#39;content&#39;</span><span class="token punctuation">]</span>
        <span class="token punctuation">}</span><span class="token punctuation">)</span>
    <span class="token comment"># 放入本次问题</span>
    messages<span class="token punctuation">.</span>append<span class="token punctuation">(</span><span class="token punctuation">{</span><span class="token string">&#39;role&#39;</span><span class="token punctuation">:</span> <span class="token string">&#39;user&#39;</span><span class="token punctuation">,</span> <span class="token string">&#39;content&#39;</span><span class="token punctuation">:</span> query<span class="token punctuation">}</span><span class="token punctuation">)</span> 

    <span class="token keyword">try</span><span class="token punctuation">:</span>
        <span class="token keyword">for</span> token <span class="token keyword">in</span> chat_stream<span class="token punctuation">(</span>messages<span class="token punctuation">)</span><span class="token punctuation">:</span>
            <span class="token comment"># 将返回的字符转换成 json 字符串，便于后续在前方拼接 &quot;data:&quot;</span>
            payload <span class="token operator">=</span> json<span class="token punctuation">.</span>dumps<span class="token punctuation">(</span><span class="token punctuation">{</span><span class="token string">&#39;type&#39;</span><span class="token punctuation">:</span> <span class="token string">&#39;content&#39;</span><span class="token punctuation">,</span> <span class="token string">&#39;text&#39;</span><span class="token punctuation">:</span> token<span class="token punctuation">}</span><span class="token punctuation">,</span> ensure_ascii<span class="token operator">=</span><span class="token boolean">False</span><span class="token punctuation">)</span>
            <span class="token keyword">yield</span> <span class="token string-interpolation"><span class="token string">f&#39;data: </span><span class="token interpolation"><span class="token punctuation">{</span>payload<span class="token punctuation">}</span></span><span class="token string">\\n\\n&#39;</span></span>
        <span class="token keyword">yield</span> <span class="token string-interpolation"><span class="token string">f&#39;data: [DONE]\\n\\n&#39;</span></span>
    <span class="token keyword">except</span> Exception <span class="token keyword">as</span> e<span class="token punctuation">:</span>
        payload <span class="token operator">=</span> json<span class="token punctuation">.</span>dumps<span class="token punctuation">(</span><span class="token punctuation">{</span><span class="token string">&#39;type&#39;</span><span class="token punctuation">:</span> <span class="token string">&#39;error&#39;</span><span class="token punctuation">,</span> <span class="token string">&#39;message&#39;</span><span class="token punctuation">:</span> <span class="token builtin">str</span><span class="token punctuation">(</span>e<span class="token punctuation">)</span><span class="token punctuation">,</span> ensure_ascii<span class="token operator">=</span><span class="token boolean">False</span><span class="token punctuation">}</span><span class="token punctuation">)</span>
        <span class="token keyword">yield</span> <span class="token string-interpolation"><span class="token string">f&#39;data: </span><span class="token interpolation"><span class="token punctuation">{</span>payload<span class="token punctuation">}</span></span><span class="token string">\\n\\n&#39;</span></span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></li><li><p>使用 SSE 流式会话的 Flask API 接口</p><div class="language-python line-numbers-mode" data-ext="py"><pre class="language-python"><code><span class="token decorator annotation punctuation">@app<span class="token punctuation">.</span>route</span><span class="token punctuation">(</span><span class="token string">&#39;/api/chat/stream&#39;</span><span class="token punctuation">,</span> methods<span class="token operator">=</span><span class="token punctuation">[</span><span class="token string">&#39;POST&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span>
<span class="token keyword">def</span> <span class="token function">chat_stream</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">:</span>
    data <span class="token operator">=</span> request<span class="token punctuation">.</span>get_json<span class="token punctuation">(</span>force<span class="token operator">=</span><span class="token boolean">True</span><span class="token punctuation">)</span>
    query <span class="token operator">=</span> data<span class="token punctuation">.</span>get<span class="token punctuation">(</span><span class="token string">&#39;message&#39;</span><span class="token punctuation">,</span> <span class="token string">&#39;&#39;</span><span class="token punctuation">)</span><span class="token punctuation">.</span>strip<span class="token punctuation">(</span><span class="token punctuation">)</span>
    session_id <span class="token operator">=</span> data<span class="token punctuation">.</span>get<span class="token punctuation">(</span><span class="token string">&#39;session_id&#39;</span><span class="token punctuation">,</span> <span class="token string">&#39;&#39;</span><span class="token punctuation">)</span><span class="token punctuation">.</span>strip<span class="token punctuation">(</span><span class="token punctuation">)</span>  <span class="token comment"># 新会话为空，后端自行生成 id，防止后端查询会话时异常</span>
    <span class="token keyword">if</span> <span class="token keyword">not</span> query<span class="token punctuation">:</span>
        <span class="token keyword">return</span> jsonify<span class="token punctuation">(</span><span class="token punctuation">{</span><span class="token string">&#39;error&#39;</span><span class="token punctuation">:</span> <span class="token string">&#39;empty message&#39;</span><span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">,</span> <span class="token number">4000</span>
    
    <span class="token comment"># 没 session id，说明是新会话，后端执行创建会话逻辑</span>
    <span class="token keyword">if</span> <span class="token keyword">not</span> session_id <span class="token keyword">or</span> <span class="token keyword">not</span> storage<span class="token punctuation">.</span>get_session<span class="token punctuation">(</span>session_id<span class="token punctuation">)</span><span class="token punctuation">:</span>
        s <span class="token operator">=</span> storage<span class="token punctuation">.</span>create_session<span class="token punctuation">(</span><span class="token punctuation">)</span>
        session_id <span class="token operator">=</span> s<span class="token punctuation">[</span><span class="token string">&#39;id&#39;</span><span class="token punctuation">]</span>
    
    <span class="token comment"># 定义一个内部方法，调用大模型，存储会话与聊天记录，返回大模型响应内容</span>
    <span class="token keyword">def</span> <span class="token function">generate</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">-</span><span class="token operator">&gt;</span> Iterator<span class="token punctuation">[</span><span class="token builtin">str</span><span class="token punctuation">]</span><span class="token punctuation">:</span>
        session <span class="token operator">=</span> storage<span class="token punctuation">.</span>get_session<span class="token punctuation">(</span>session_id<span class="token punctuation">)</span>
        <span class="token comment"># 获取该会话的完整消息历史记录</span>
        history <span class="token operator">=</span> session<span class="token punctuation">.</span>get<span class="token punctuation">(</span><span class="token string">&#39;message&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token punctuation">)</span> <span class="token keyword">if</span> session esle <span class="token punctuation">[</span><span class="token punctuation">]</span>
        <span class="token comment"># 存储大模型的完整响应文本，用于存储到历史记录中</span>
        full_answer <span class="token operator">=</span> <span class="token string">&#39;&#39;</span>
        <span class="token comment"># 调用 SSE 流式会话函数</span>
        <span class="token keyword">for</span> sse_line <span class="token keyword">in</span> stream_chat<span class="token punctuation">(</span>history<span class="token punctuation">,</span> query<span class="token punctuation">)</span><span class="token punctuation">:</span>
            <span class="token comment"># 存储大模型的完整响应内容</span>
            <span class="token keyword">if</span> sse_line<span class="token punctuation">.</span>strip<span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">:</span>
                <span class="token comment"># 某个字节出现问题时，跳过该字节</span>
                <span class="token keyword">try</span><span class="token punctuation">:</span>
                    raw <span class="token operator">=</span> sse_line<span class="token punctuation">.</span>replace<span class="token punctuation">(</span><span class="token string">&#39;data: &#39;</span><span class="token punctuation">,</span> <span class="token string">&#39;&#39;</span><span class="token punctuation">)</span><span class="token punctuation">.</span>strip<span class="token punctuation">(</span><span class="token punctuation">)</span>
                    <span class="token keyword">if</span> raw <span class="token keyword">and</span> raw <span class="token operator">!=</span> <span class="token string">&#39;[DONE]&#39;</span><span class="token punctuation">:</span>
                        d <span class="token operator">=</span> json<span class="token punctuation">.</span>loads<span class="token punctuation">(</span>raw<span class="token punctuation">)</span>
                        <span class="token keyword">if</span> d<span class="token punctuation">.</span>get<span class="token punctuation">(</span><span class="token string">&#39;type&#39;</span><span class="token punctuation">)</span> <span class="token operator">==</span> <span class="token string">&#39;content&#39;</span><span class="token punctuation">:</span>
                            full_anwser <span class="token operator">+=</span> d<span class="token punctuation">.</span>get<span class="token punctuation">(</span><span class="token string">&#39;text&#39;</span><span class="token punctuation">:</span> <span class="token string">&#39;&#39;</span><span class="token punctuation">)</span>
                <span class="token keyword">except</span> Exception<span class="token punctuation">:</span>
                    <span class="token keyword">pass</span>
            <span class="token comment"># 该函数直接返回 SSE 流</span>
            <span class="token keyword">yield</span> sse_line
    
        <span class="token keyword">if</span> session<span class="token punctuation">:</span>
            <span class="token comment"># 追加历史记录</span>
            session<span class="token punctuation">[</span><span class="token string">&#39;message&#39;</span><span class="token punctuation">]</span><span class="token punctuation">.</span>append<span class="token punctuation">(</span><span class="token punctuation">{</span><span class="token string">&#39;role&#39;</span><span class="token punctuation">:</span> <span class="token string">&#39;user&#39;</span><span class="token punctuation">,</span> <span class="token string">&#39;content&#39;</span><span class="token punctuation">:</span> query<span class="token punctuation">}</span><span class="token punctuation">)</span>
            session<span class="token punctuation">[</span><span class="token string">&#39;message&#39;</span><span class="token punctuation">]</span><span class="token punctuation">.</span>append<span class="token punctuation">(</span><span class="token punctuation">{</span><span class="token string">&#39;role&#39;</span><span class="token punctuation">:</span> <span class="token string">&#39;assistant&#39;</span><span class="token punctuation">,</span> <span class="token string">&#39;content&#39;</span><span class="token punctuation">:</span> full_answer<span class="token punctuation">}</span><span class="token punctuation">)</span>

            <span class="token comment"># 没有标题或标题是系统自动自动生成的，创建一个新标题</span>
            <span class="token keyword">if</span> <span class="token keyword">not</span> session<span class="token punctuation">.</span>get<span class="token punctuation">(</span><span class="token string">&#39;title&#39;</span><span class="token punctuation">)</span> <span class="token keyword">or</span> session<span class="token punctuation">[</span><span class="token string">&#39;title&#39;</span><span class="token punctuation">]</span><span class="token punctuation">.</span>startswith<span class="token punctuation">(</span><span class="token string">&#39;会话 &#39;</span><span class="token punctuation">)</span><span class="token punctuation">:</span>
                <span class="token comment"># 截取问题的前 30 字符作为新标题</span>
                session<span class="token punctuation">[</span><span class="token string">&#39;title&#39;</span><span class="token punctuation">]</span> <span class="token operator">=</span> query<span class="token punctuation">[</span><span class="token punctuation">:</span><span class="token number">30</span><span class="token punctuation">]</span>  <span class="token operator">+</span> <span class="token punctuation">(</span><span class="token string">&#39;...&#39;</span> <span class="token keyword">if</span> <span class="token builtin">len</span><span class="token punctuation">(</span>query<span class="token punctuation">)</span> <span class="token operator">&gt;</span> <span class="token number">30</span> <span class="token keyword">else</span> <span class="token string">&#39;&#39;</span><span class="token punctuation">)</span>
            storage<span class="token punctuation">.</span>save_session<span class="token punctuation">(</span>session<span class="token punctuation">)</span>

    <span class="token keyword">return</span> Response<span class="token punctuation">(</span>
        generate<span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">,</span>  <span class="token comment"># 将 yield 的 SSE 流直接返回。流式返回需要 yield 返回值</span>
        mimetype<span class="token operator">=</span><span class="token string">&#39;text/event-stream&#39;</span><span class="token punctuation">,</span>  <span class="token comment"># 设置相应内容为流式</span>
        headers<span class="token operator">=</span><span class="token punctuation">{</span>
            <span class="token string">&#39;Cache-Control&#39;</span><span class="token punctuation">:</span> <span class="token string">&#39;no-cache&#39;</span><span class="token punctuation">,</span>
            <span class="token string">&#39;Connection&#39;</span><span class="token punctuation">:</span> <span class="token string">&#39;keep-alive&#39;</span><span class="token punctuation">,</span>
            <span class="token string">&#39;X-Accel-Buffering&#39;</span><span class="token punctuation">:</span> <span class="token string">&#39;no&#39;</span>
        <span class="token punctuation">}</span>
    <span class="token punctuation">)</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></li></ul>`,10);function h(_,w){const a=o("ExternalLinkIcon");return c(),i("div",null,[u,n("p",null,[n("a",k,[s("参考内容"),t(a)])]),r,n("ul",null,[d,n("li",null,[s("索引: 共两个步骤 "),n("ul",null,[n("li",null,[s("通过 Embedding 将片段文本转换成向量。语句通过 "),n("a",v,[s("Embedding 模型"),t(a)]),s(" 转换成向量，含义相近的语句会解析成相近的向量")]),m])])]),b,n("p",null,[s("此处需要调用大模型，这里以 gemini 为例，在 "),n("a",g,[s("Google AI Studio"),t(a)]),s(" 页面创建一个 API KEY")]),y])}const x=e(l,[["render",h],["__file","031.html.vue"]]);export{x as default};
